import {progressGuard,revisionKey} from '../shared/progress.js';
import {chapters,textbook} from '../shared/course.js';
import {comparisons} from './comparisons.js?v=c3-6';
import {renderLab,bindLab} from './labs.js?v=c3-6';
import {modules} from './content.js?v=c3-6';
import {diagrams,references} from './diagrams.js?v=c3-6';
import {buildBank,createSession,grade,score,practicePool} from './engine.js?v=c3-6';
const ASSESSMENTS=true,LABS=true;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='soma-cell-studio-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
const bank=buildBank(modules,diagrams),state={page:'home',module:modules.some(m=>m.id===saved.module)?saved.module:modules[0].id,tab:'learn',compareReveal:false,lesson:0,diagram:0,target:0,labels:true,revealed:false,reference:0,recall:0,flip:false,glossary:0,query:'',filter:'all',stats:saved.stats&&typeof saved.stats==='object'?saved.stats:{},session:null,review:0,storageError:false};
let cleanupLab;
const mod=()=>modules.find(m=>m.id===state.module),ds=()=>diagrams[state.module]||[],rs=()=>references.filter(r=>r.section===state.module||r.section===mod().section||r.module===state.module);
const canSaveProgress=typeof window==='undefined'?()=>true:progressGuard(localStorage,()=>location.replace('../#/review'));
if(typeof window!=='undefined')window.addEventListener('storage',ev=>{if(ev.key===revisionKey)canSaveProgress();});
function persist(){if(!canSaveProgress())return;try{const prior=JSON.parse(localStorage.getItem(key)||'{}').stats||{};for(const [id,v] of Object.entries(prior))if(!state.stats[id]||(v.updatedAt||0)>(state.stats[id].updatedAt||0))state.stats[id]=v;localStorage.setItem(key,JSON.stringify({module:state.module,stats:state.stats}));}catch{state.storageError=true;}}
const mastered=id=>bank.filter(q=>q.module===id&&state.stats[q.id]?.lastCorrect&&!state.stats[q.id]?.assisted).length;
function heading(k,t,d=''){return `<div class="main-heading"><div><p class="eyebrow">${esc(k)}</p><h1>${esc(t)}</h1></div>${d?`<span class="pill">${esc(d)}</span>`:''}</div>`;}
function pager(id,i,n){if(id==='lesson'&&i===n-1){const next=modules[modules.findIndex(m=>m.id===state.module)+1];return `<div class="pager"><button data-page="lesson" data-delta="-1" ${i===0?'disabled':''}>← Previous lesson</button><span>${i+1} / ${n}</span><button class="primary" data-tab="practice">Practice this section →</button>${next?`<button data-module="${next.id}">Continue to ${next.section} →</button>`:'<button data-nav="exam">Chapter exam →</button>'}</div>`;}return `<div class="pager"><button data-page="${id}" data-delta="-1" ${i<=0?'disabled':''}>← Previous ${id==='lesson'?'lesson':'card'}</button><span>${i+1} / ${n}</span><button data-page="${id}" data-delta="1" ${i>=n-1?'disabled':''}>Next ${id==='lesson'?'lesson':'card'} →</button></div>`;}
function header(){return `<header class="app-header"><a class="brand" href="../">soma<span>/ learning studio</span></a><select id="chapter-switch" class="shared-chapters" aria-label="Choose chapter">${chapters.map(c=>`<option value="${c.id}" ${c.id===3?'selected':''}>Chapter ${c.id} · ${c.short}</option>`).join('')}</select><div class="header-links"><a href="../">Chapters</a><a href="../#/review">Review & progress</a><a href="../#/help">Help</a></div></header>`;}
function sidebar(){return `<aside class="sidebar"><p class="eyebrow">CHAPTER 3</p><a href="../#/chapter/3">Chapter overview ↗</a><nav aria-label="Chapter 3 sections">${modules.map((m,i)=>`<a class="section-route ${state.module===m.id?'active':''}" href="#module/${m.id}/learn"><b>${m.section}</b> ${esc(chapters[2].sections[i][1])}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#exam">Chapter exam →</a><br><a href="#review">Review chapter →</a><br><button data-nav="glossary">Glossary</button><button data-nav="sources">Sources</button></div></aside>`;}
function footer(){return `<footer class="footer"><span><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/3-introduction" target="_blank" rel="noopener">Access for free at openstax.org · Chapter 3</a> · CC BY-NC-SA 4.0</span><span>${state.storageError?'Storage unavailable; this session still works.':'Progress stays on this device · reviewed Chapter 3 practice'}</span></footer>`;}
function home(){return `${heading('SMALL STRUCTURES. EXTRAORDINARY POSSIBILITIES.','Life, from the inside.','6 connected modules')}<section class="hero"><div class="hero-copy"><p class="eyebrow">WELCOME TO CELL STUDIO</p><h2>One cell. A whole world to discover.</h2><p>Explore its structures. Experiment with its processes. Turn the cellular level of organization into something you can see, explain and remember.</p><div class="hero-actions"><button class="primary" data-module="${state.module}">Enter the studio →</button><button data-nav="${ASSESSMENTS?'exam':'glossary'}">${ASSESSMENTS?'Test the whole chapter':'Explore the vocabulary'}</button></div></div><div class="cell-emblem" aria-hidden="true"><i></i><i></i><i></i></div></section><div class="module-grid">${modules.map(m=>{const n=bank.filter(q=>q.module===m.id).length,good=mastered(m.id);return `<button class="module-card" data-module="${m.id}"><div class="card-top"><span class="eyebrow">SECTION ${esc(m.section)}</span><span>↗</span></div><h3>${esc(m.title)}</h3><p>${esc(m.tagline)}</p><div class="card-foot"><span>${good?`${good} / ${n} recalled`:`${m.lessons.length} lessons · ${(diagrams[m.id]||[]).length} ${(diagrams[m.id]||[]).length===1?'diagram':'diagrams'}`}</span><progress aria-label="${esc(m.title)} independently recalled questions" max="${n}" value="${good}"></progress></div></button>`;}).join('')}</div>`;}
function moduleView(){const m=mod(),i=modules.findIndex(x=>x.id===m.id),explore=['diagram','reference','compare','lab'],group=explore.includes(state.tab)?'explore':state.tab==='recall'?'practice':state.tab;const nav=[['learn','Learn'],['diagram','Explore'],['practice','Practice'],['review','Review']];return `<p class="breadcrumb"><a href="../">Chapters</a> / <a href="../#/chapter/3">Chapter 3</a> / ${m.section} · <a href="${textbook(chapters[2].sections[i])}" target="_blank" rel="noopener">Read textbook ↗</a></p>${heading('SECTION '+m.section,chapters[2].sections[i][1],`${m.lessons.length} lessons`)}<div class="tabs" aria-label="Section activities">${nav.map(([id,n])=>`<button data-tab="${id}" aria-pressed="${group===(id==='diagram'?'explore':id)}">${n}</button>`).join('')}<a href="../local-ai/?topic=${m.id}&tool=tutor">AI tutor ↗</a><a href="../local-ai/?topic=${m.id}&tool=quiz">AI practice ↗</a></div>${explore.includes(state.tab)?`<div class="activity-subnav">${[['diagram','Label diagrams'],['reference','Textbook figures'],['compare','Compare ideas'],['lab','Process lab']].map(([id,n])=>`<button data-tab="${id}" aria-pressed="${state.tab===id}">${n}</button>`).join('')}</div>`:['practice','recall'].includes(state.tab)?`<div class="activity-subnav"><button data-tab="practice">Reviewed quiz</button><button data-tab="recall">Flashcards · ungraded</button></div>`:''}${state.tab==='review'?reviewHub(false):state.tab==='diagram'?diagramView():state.tab==='reference'?referenceView():state.tab==='compare'?compareView():state.tab==='recall'?recallView():state.tab==='practice'?setup(false):state.tab==='lab'?'<section class="panel lab-container" id="lab-container"></section>':learnView()}`;}
function reviewHub(whole=true){const pool=bank.filter(q=>(whole||q.module===state.module)&&(state.stats[q.id]?.lastCorrect===false||state.stats[q.id]?.assisted));return `<section class="panel lesson"><p class="eyebrow">${whole?'CHAPTER':'SECTION'} REVIEW</p><h2>${pool.length?pool.length+' questions to revisit':'A fresh start for your recall.'}</h2><p>${pool.length?'These questions were missed or answered with help on your latest attempt.':'No missed or assisted questions are recorded here yet. Start practice to find what needs another look.'}</p><button class="primary" data-course-review="${whole?'all':'section'}" ${pool.length?'':'disabled'}>Practice missed & assisted →</button><button data-tab="practice" data-review-start>Open section practice</button><p class="small muted">A correct answer without help shows independent recall on that attempt. It is not a guarantee of mastery.</p></section>`;}
const learningGoals={
 membrane:'Explain how membrane structure controls transport; predict water movement; distinguish passive, active and vesicular transport.',
 organelles:'Connect each organelle to its function; trace a secreted protein; compare the three cytoskeletal systems.',
 nucleus:'Connect nuclear structures to their jobs; pair DNA bases with strand direction; explain semiconservative replication.',
 protein:'Distinguish replication, transcription and translation; trace RNA processing; interpret codons and anticodons.',
 division:'Sequence the cell cycle; distinguish chromosomes from chromatids; explain checkpoints and the consequences of failed control.',
 differentiation:'Connect gene expression to specialization; compare potency levels; distinguish stem-cell sources and limits of proposed therapies.'
};
function recallHint(q){return q.type==='locate'?'Use the surrounding structures and the end of each callout line to orient yourself before selecting a marker.':q.type==='typed'?'Describe the structure’s location and job in your own words first. Then retrieve the matching term.':'Identify what changes in the scenario. Compare each option with the mechanism or sequence it would require, and eliminate contradictions.';}
function learnView(){const m=mod(),l=m.lessons[state.lesson];return `<div class="workspace"><section class="panel lesson"><label class="form-row small">Jump to lesson<select id="lesson-select">${m.lessons.map((item,i)=>`<option value="${i}" ${i===state.lesson?'selected':''}>${i+1}. ${esc(item.title)}</option>`).join('')}</select></label><details class="practice-customize"><summary>What to master in ${m.section}</summary><p>${esc(learningGoals[m.id])}</p><p>Learn the idea, test it in Explore, then use Practice and Review to find what needs another pass.</p></details><h2>${esc(l.title)}</h2><p class="body">${esc(l.body)}</p><details class="practice-customize"><summary>Pause & explain · ungraded</summary><p>Look away from the explanation. Explain “${esc(l.title)}” in your own words, give an example, and name one common mix-up. Reopen the lesson to check your reasoning.</p><button data-tab="practice">Check my recall with practice →</button></details>${pager('lesson',state.lesson,m.lessons.length)}</section><section class="panel lesson"><div class="tip"><b>Make it stick</b><p>${esc(l.analogy)}</p></div><div><p class="eyebrow">A COMMON MIX-UP</p><p class="trap">${esc(l.trap)}</p></div><div class="hero-actions"><button data-tab="diagram">See the structures ↗</button>${LABS?'<button data-tab="lab">Try the experiment ↗</button>':''}</div></section></div>`;}
function figure(d,{quiz=false,locate=false,target=-1,reveal=false,review=false}={}){const active=quiz?((!locate||reveal)?target:-1):state.target;return `<section class="panel figure-panel"><div class="panel-bar"><strong>${esc(d.title)}</strong>${quiz?'<span class="eyebrow">LABEL LAB</span>':`<label class="label-toggle"><input id="labels" type="checkbox" ${state.labels?'checked':''}>Labels</label>`}</div><div class="diagram-stage"><div class="diagram-wrap">${d.svg}${d.targets.map((t,i)=>`<button class="diagram-pin ${i===active?'active':''}" style="left:${t.x}%;top:${t.y}%" data-target="${i}" aria-label="${quiz||!state.labels?'Marker '+(i+1):esc(t.name)}" ${review||quiz&&(!locate||state.session?.answered)?'disabled':''}>${i+1}</button>`).join('')}</div></div>${!quiz?`<div class="diagram-key">${d.targets.map((t,i)=>`<button data-target="${i}" aria-pressed="${i===state.target}">${i+1}${state.labels?' · '+esc(t.name):''}</button>`).join('')}</div>`:''}<div class="figure-note">Teaching schematic · not to scale · OpenStax Chapter 3</div></section>`;}
function diagramView(){const views=ds(),d=views[state.diagram],t=d.targets[state.target];return `<div class="toolbar"><label class="small">Diagram <select id="diagram-select">${views.map((x,i)=>`<option value="${i}" ${i===state.diagram?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><span class="small muted">Select a number.</span></div><div class="workspace">${figure(d)}<section class="panel lesson"><p class="eyebrow">STRUCTURE ${state.target+1} / ${d.targets.length}</p>${state.labels||state.revealed?`<h2>${esc(t.name)}</h2><p class="body">${esc(t.description)}</p>`:'<h2>Retrieve the name.</h2><p>Say its name and explain its role before revealing the answer.</p><button class="primary" data-action="reveal">Reveal this label</button>'}<p class="small muted">${esc(d.description)}</p><div class="pager"><button data-target="${(state.target+d.targets.length-1)%d.targets.length}">← Previous</button><span>${state.target+1} / ${d.targets.length}</span><button data-target="${(state.target+1)%d.targets.length}">Next →</button></div></section></div>`;}
function referenceView(){const refs=rs();if(!refs.length)return '<section class="panel lesson"><h2>Read the original section</h2><p>Use the OpenStax source link below to read this section.</p></section>';const r=refs[state.reference%refs.length];return `<section class="panel figure-panel" style="flex:1"><div class="panel-bar"><strong>${esc(r.title)}</strong><span class="small">Original · labels visible</span></div><div class="reference-stage"><img src="${esc(r.file)}" alt="${esc(r.caption||r.title)}"></div><div class="reference-caption">${esc(r.caption)} <span class="small">© Rice University · CC BY-NC-SA 4.0 · book page ${esc(r.page)}</span></div><div style="padding:9px 16px">${pager('reference',state.reference,refs.length)}</div></section>`;}
function compareView(){const c=comparisons[state.module];return `<section class="comparison"><h2>${esc(c.title)}</h2><div class="compare-grid">${c.items.map(item=>`<article class="panel compare-card"><h3>${esc(item.name)}</h3><strong>${esc(item.rule)}</strong><p>${esc(item.how)}</p><p class="muted">${esc(item.example)}</p><span>${esc(item.energy)}</span></article>`).join('')}</div><section class="panel compare-check"><p><b>Explain it first:</b> ${esc(c.question)}</p>${state.compareReveal?`<p class="compare-answer" role="status">${esc(c.answer)}</p>`:'<button data-action="compare-reveal">Reveal the reasoning</button>'}</section></section>`;}
function recallView(){const ts=mod().terms,t=ts[state.recall];return `<section class="panel lesson" style="flex:1"><p class="eyebrow">ACTIVE RECALL · SAY IT BEFORE YOU REVEAL IT</p><div class="recall-face"><h2>${state.flip?esc(t.term):'Which term fits?'}</h2><p>${esc(t.definition)}</p>${state.flip?'<span class="answer">Connect the name to its meaning.</span>':'<button class="primary" data-action="flip">Reveal the term</button>'}</div>${pager('recall',state.recall,ts.length)}</section>`;}
function glossary(){const ts=modules.flatMap(m=>m.terms.map(t=>({...t,module:m.id,section:m.section}))).filter(t=>(state.filter==='all'||t.module===state.filter)&&`${t.term} ${t.definition}`.toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>a.term.localeCompare(b.term));const total=Math.max(1,Math.ceil(ts.length/6));state.glossary=Math.min(state.glossary,total-1);return `${heading('THE WORDS BEHIND THE STRUCTURES','Cell dictionary',`${ts.length} terms`)}<div class="glossary-controls"><input id="term-search" type="search" value="${esc(state.query)}" placeholder="Search a term or meaning…" aria-label="Search cell dictionary"><select id="term-filter" aria-label="Filter dictionary by module"><option value="all">All Chapter 3</option>${modules.map(m=>`<option value="${m.id}" ${state.filter===m.id?'selected':''}>${m.section} · ${esc(m.title)}</option>`).join('')}</select></div><div class="glossary-list">${ts.slice(state.glossary*6,state.glossary*6+6).map(t=>`<article class="term-card"><span class="eyebrow">SECTION ${esc(t.section)}</span><h3>${esc(t.term)}</h3><p>${esc(t.definition)}</p></article>`).join('')||'<p>No matching terms. Try another word.</p>'}</div>${pager('glossary',state.glossary,total)}`;}
function setup(exam){return `${exam?heading('CONNECT THE ENTIRE CHAPTER','Your cellular checkpoint.','Chapter 3 only'):''}<div class="setup-grid"><section class="panel lesson"><p class="eyebrow">${exam?'CHAPTER EXAM':'MODULE PRACTICE'}</p><h2>${exam?'Six topics. One connected picture.':'Build your recall.'}</h2>${exam?'':'<p>Start with 10 mixed questions from this section.</p><details class="practice-customize"><summary>Customize practice</summary>'}<label class="form-row">Answer format<select id="format"><option value="mixed">Mixed: concepts, labels & locations</option><option value="choice">Multiple choice</option><option value="typed">Type the term or label</option><option value="locate">Locate on a diagram</option></select></label><label class="form-row">Session length<select id="count">${(exam?[30,60]:[10,20]).map(n=>`<option value="${n}">${n} questions</option>`).join('')}<option value="all">All available questions</option></select></label>${exam?'':'</details>'}<p class="small muted">${exam?'Balanced across all six modules. Explanations appear after submission.':'Feedback after every answer. Hints count as assisted recall.'}</p><button class="primary" data-action="${exam?'exam':'practice'}">${exam?'Begin chapter exam':'Start practice'} →</button></section><section class="panel lesson"><h2>Understand it. Then retrieve it.</h2><p>Identify structures, connect them to their functions, and predict what happens when a process changes.</p><div class="tip"><b>Make your result meaningful</b><p>Say your reasoning before you answer. Study the explanation even when your answer is correct.</p></div>${exam?'':`<label class="form-row">Practice focus<select id="practice-focus"><option value="all">All questions in this module</option><option value="revisit">Previously missed or assisted</option><option value="untried">Not attempted yet</option></select></label>`}<p class="small muted" id="pool-count" role="status">${exam?bank.length:bank.filter(q=>q.module===state.module).length} questions available.</p><p class="small muted"> A shorter pool uses all available questions. Your answers and unfinished session are saved on this device. Reload to resume the same question.</p></section></div>`;}
function updatePoolCount(){const exam=state.page==='exam',pool=practicePool(bank,{module:exam?null:state.module,format:$('#format').value,focus:exam?'all':$('#practice-focus').value,stats:state.stats});$('#pool-count').textContent=`${pool.length} matching questions available.${pool.length?'':' Choose another focus or format.'}`;document.querySelector('[data-action="'+(exam?'exam':'practice')+'"]').disabled=!pool.length;}
function start(exam=false,retry=null){const questions=retry||createSession(bank,{module:exam?null:state.module,exam,focus:exam?'all':$('#practice-focus').value,stats:state.stats,format:$('#format').value,count:$('#count').value==='all'?'all':Number($('#count').value)});if(!questions.length)return;state.session={exam,questions,index:0,records:[],answered:false,hint:false,draft:''};state.page='quiz';render();}
function quiz(){const s=state.session,q=s.questions[s.index],m=modules.find(x=>x.id===q.module),d=(diagrams[q.module]||[]).find(x=>x.id===q.diagram),r=s.records.at(-1);return `<div class="quiz-top"><span>${s.exam?'CHAPTER EXAM':'PRACTICE'} · ${esc(m.title)} · ${s.index+1} / ${s.questions.length}</span><button data-action="end">End session</button></div><progress class="quiz-progress" max="${s.questions.length}" value="${s.index}"></progress><h1 class="question-heading" tabindex="-1" id="question">${esc(q.prompt)}</h1><div class="workspace quiz-workspace">${d?figure(d,{quiz:true,locate:q.type==='locate',target:q.target,reveal:s.answered&&!s.exam}):`<section class="panel question-card"><span class="orb">${esc(m.section)}</span><p class="eyebrow">${q.type==='typed'?'RETRIEVE THE TERM':'REASON IT THROUGH'}</p><h2>${esc(m.title)}</h2><p class="muted">${s.exam?'Review explanations after submission.':'Pause and predict before answering.'}</p></section>`}<section class="panel lesson">${q.type==='choice'&&s.answered?`<div class="feedback">Your answer: <strong>${esc(r.value)}</strong></div>`:q.type==='choice'?`<div class="choices">${q.options.map((o,i)=>`<button data-answer="${i}" ${s.answered?'disabled':''} class="${s.answered&&!s.exam?(o===q.answer?'correct':r.value===o?'wrong':''):''}"><b>${String.fromCharCode(65+i)}</b>${esc(o)}</button>`).join('')}</div>`:q.type==='typed'?`<form id="answer-form" class="form-row"><label for="typed">Your answer</label><input id="typed" value="${esc(s.draft)}" placeholder="Type the term…" autocomplete="off" ${s.answered?'disabled':''}><button class="primary" ${s.answered?'disabled':''}>Check answer</button></form>`:'<p>Select a numbered structure on the diagram.</p>'}${!s.answered&&!s.exam?`<button data-action="hint">${s.hint?'Hint shown · assisted recall':'Show a hint'}</button>${s.hint?`<div class="feedback">${esc(recallHint(q))}</div>`:''}`:''}${s.answered?`<div class="feedback ${s.exam?'':r.correct?'good':'bad'}" role="status"><b>${s.exam?'Answer recorded.':r.correct?(r.assisted?'Correct with help.':'Correct.'):'Review this one.'}</b>${!s.exam?`<p>${esc(q.answerText||q.answer)} — ${esc(q.explanation)}</p>`:'<p>Review your answer after submission.</p>'}</div><button class="primary" data-action="next">${s.index===s.questions.length-1?(s.exam?'Submit exam':'See results'):'Next question'} →</button>`:'<button data-action="skip">Skip question</button>'}</section></div>`;}
function recordAnswer(q,value,assisted=false){const correct=grade(q,value);state.session.records.push({q,value,correct,assisted});const prev=state.stats[q.id]||{attempts:0};state.stats[q.id]={attempts:prev.attempts+1,lastCorrect:correct,assisted,updatedAt:Date.now()};}
function endSession(){const s=state.session;for(let i=s.index+(s.answered?1:0);i<s.questions.length;i++)recordAnswer(s.questions[i],'Skipped');persist();state.page='results';state.review=0;render();}
function submit(value){const s=state.session;if(!s||s.answered)return;const q=s.questions[s.index];recordAnswer(q,value,s.hint);s.answered=true;persist();render();}
function results(){const s=state.session,r=s.records[state.review],n=score(s.records),q=r.q,d=(diagrams[q.module]||[]).find(x=>x.id===q.diagram),value=q.type==='locate'&&typeof r.value==='number'?(diagrams[q.module]||[]).find(d=>d.id===q.diagram)?.targets[r.value]?.name:r.value;return `${heading('YOUR NEXT STEP IS CLEAR','Recall, then refine.',`${n.independent} / ${n.total} independently correct`)}<div class="toolbar"><div class="stats-row"><span class="score">${Math.round(n.independent/n.total*100)}%</span><span class="small muted">${n.assisted} assisted · ${n.missed} to revisit</span></div><div class="tabs"><button data-action="retry" ${n.missed?'':'disabled'}>Retry missed & assisted</button><a href="../#/chapter/3">Chapter overview →</a></div></div><div class="workspace"><section class="panel lesson"><p class="eyebrow">ANSWER ${state.review+1} · ${r.assisted?'ASSISTED':r.correct?'CORRECT':'REVIEW'}</p><h2>${esc(q.prompt)}</h2><p>Your answer: <strong>${esc(value)}</strong></p><p>Correct answer: <strong>${esc(q.answerText||q.answer)}</strong></p><p>${esc(q.explanation)}</p><button data-action="review-topic">Study this topic ↗</button>${pager('review',state.review,s.records.length)}</section>${d?figure(d,{quiz:true,locate:true,target:q.target,reveal:true,review:true}):`<section class="panel lesson"><p class="eyebrow">RECONNECT THE IDEA</p><h2>${esc(modules.find(m=>m.id===q.module).title)}</h2><p>Revisit the lesson or explore the structure before trying again.</p><button class="primary" data-action="review-topic">Study this topic ↗</button><div class="tip"><b>What your score means</b><p>Only correct answers without a hint count as independent recall. Skipped and assisted questions stay in your retry set.</p></div></section>`}</div>`;}
function sourcesView(){return `${heading('THE THINKING BEHIND THE STUDIO','Sources & controls')}<section class="panel lesson source-box" style="flex:1"><h2>Built around your Chapter 3.</h2><p>OpenStax <em>Anatomy and Physiology 2e</em>, supplied 2026 edition. Chapter 3, PDF pages 101–144. Textbook figures © Rice University, CC BY-NC-SA 4.0. Original schematics and activities are educational adaptations, not to scale. No OpenStax endorsement is implied.</p><p><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/3-introduction" target="_blank" rel="noopener">Read the complete chapter ↗</a></p><p>Learn provides short lessons. Diagram atlas offers labels. Textbook shows original figures. Compare separates commonly confused ideas. Recall cards retrieve key terms.${LABS?' Experiment lets you change conditions and build processes.':''}${ASSESSMENTS?' Practice gives immediate feedback and can focus on missed, assisted, or untried questions; Chapter exam holds feedback until submission.':''}</p><p>Tab moves through controls; Enter or Space selects. All activities have button or keyboard controls. Chapter 3 progress is stored separately in this browser.</p><button data-action="reset">Reset Chapter 3 progress</button></section>`;}
function leave(){return state.page!=='quiz'||confirm('Leave this unfinished session? Submitted answers remain saved.');}
function selectModule(id){if(!leave())return;state.module=id;state.page='module';state.session=null;state.tab='learn';state.lesson=state.diagram=state.target=state.reference=state.recall=0;state.revealed=state.flip=state.compareReveal=false;persist();render();}
function render(){if(typeof window!=='undefined')saveCellPosition();const focused=document.activeElement;const focusKey=focused?.id?['id',focused.id]:['data-tab','data-page','data-target','data-action'].map(a=>[a,focused?.getAttribute?.(a)]).find(([,v])=>v!=null);cleanupLab?.();cleanupLab=null;const body=state.page==='home'?home():state.page==='module'?moduleView():state.page==='glossary'?glossary():state.page==='exam'?setup(true):state.page==='quiz'?quiz():state.page==='results'?results():state.page==='review'?reviewHub(true):sourcesView();$('#app').innerHTML=header()+`<div class="shell">${sidebar()}<main class="main" id="main"><select class="mobile-module" id="mobile-module" aria-label="Choose a Chapter 3 module"><option value="">Choose a module…</option>${modules.map(m=>`<option value="${m.id}" ${state.page==='module'&&m.id===state.module?'selected':''}>${m.section} · ${esc(m.title)}</option>`).join('')}</select>${body}${footer()}</main></div>`;bind();if(state.page==='module'&&state.tab==='lab'){const box=$('#lab-container');box.innerHTML=renderLab(state.module);cleanupLab=bindLab(box,state.module);}if(state.page==='quiz')$('#question')?.focus({preventScroll:true});else if(focusKey){const [a,v]=focusKey;[...document.querySelectorAll(`[${a}]`)].find(el=>el.getAttribute(a)===v&&(a!=='data-page'||el.getAttribute('data-delta')===focused.getAttribute('data-delta'))&&!el.disabled)?.focus({preventScroll:true});}}
function bind(){
 document.querySelector('.skip')?.addEventListener('click',e=>{e.preventDefault();$('#main')?.setAttribute('tabindex','-1');$('#main')?.focus();});

 $('#chapter-switch')?.addEventListener('change',e=>{if(leave())location.href='../#/chapter/'+e.target.value;});
 document.querySelectorAll('[data-course-review]').forEach(b=>b.onclick=()=>{const qs=bank.filter(q=>(b.dataset.courseReview==='all'||q.module===state.module)&&(state.stats[q.id]?.lastCorrect===false||state.stats[q.id]?.assisted));if(qs.length)start(false,qs);});

 $('#format')?.addEventListener('change',updatePoolCount);$('#practice-focus')?.addEventListener('change',updatePoolCount);
 document.querySelectorAll('a[href^="../"]').forEach(a=>a.onclick=e=>{if(!leave())e.preventDefault();});
 document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>selectModule(b.dataset.module));$('#mobile-module')?.addEventListener('change',e=>{if(e.target.value)selectModule(e.target.value);});
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();if(!leave())return;state.page=b.dataset.nav;state.session=null;render();});
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.page='module';state.tab=b.dataset.tab;state.compareReveal=false;render();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state[b.dataset.page]+=Number(b.dataset.delta);state.flip=false;render();});
 document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.target);if(state.page==='quiz')submit(i);else{state.target=i;state.revealed=false;render();}});
 $('#lesson-select')?.addEventListener('change',e=>{state.lesson=Number(e.target.value);render();});$('#labels')?.addEventListener('change',e=>{state.labels=e.target.checked;state.revealed=false;render();});$('#diagram-select')?.addEventListener('change',e=>{state.diagram=Number(e.target.value);state.target=0;state.revealed=false;render();});
 $('#term-filter')?.addEventListener('change',e=>{state.filter=e.target.value;state.glossary=0;render();});$('#term-search')?.addEventListener('input',e=>{state.query=e.target.value;state.glossary=0;render();$('#term-search').focus();});
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>submit(state.session.questions[state.session.index].options[Number(b.dataset.answer)]));$('#typed')?.addEventListener('input',e=>{state.session.draft=e.target.value;if(typeof window!=='undefined')saveCellPosition();});$('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();const value=$('#typed').value.trim();if(value)submit(value);});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'compare-reveal':state.compareReveal=true;render();break;case'reveal':state.revealed=true;render();break;case'flip':state.flip=true;render();break;case'practice':start();break;case'exam':start(true);break;case'hint':state.session.hint=true;render();break;case'skip':submit('Skipped');break;case'next':{const s=state.session;if(s.index===s.questions.length-1){state.page='results';state.review=0;}else{s.index++;s.answered=false;s.hint=false;s.draft='';}render();break;}case'end':if(confirm('End this session and mark unanswered questions as skipped?')){endSession();}break;case'retry':start(false,state.session.records.filter(r=>!r.correct||r.assisted).map(r=>r.q));break;case'review-topic':{const q=state.session.records[state.review].q;state.page='module';state.module=q.module;state.session=null;state.lesson=state.reference=state.recall=0;state.flip=state.revealed=false;state.diagram=Math.max(0,ds().findIndex(d=>d.id===q.diagram));state.target=q.target??0;state.labels=true;state.tab=q.diagram?'diagram':'learn';persist();render();break;}case'reset':location.href='../#/review';break;}});
}
if(typeof window!=='undefined')window.addEventListener('beforeunload',e=>{if(state.page==='quiz'){e.preventDefault();e.returnValue='';}});

let applyingRoute=false;
function cellRoute(){if(state.page==='module')return `module/${state.module}/${state.tab}/${state.lesson}/${state.diagram}/${state.target}`;return state.page;}
function saveCellPosition(){if(!canSaveProgress())return;try{const url=cellRoute();if(!applyingRoute&&location.hash.slice(1)!==url)history.pushState(null,'','#'+url);if(state.page==='module'||state.page==='quiz')localStorage.setItem('soma-resume-v1',JSON.stringify({label:`${mod().section} · ${state.page==='quiz'?'unfinished practice':mod().title}`,url:'chapter3/#'+url}));localStorage.setItem('soma-cell-draft-v1',JSON.stringify({state}));document.documentElement.dataset.motion=JSON.parse(localStorage.getItem('soma-motion')||'"on"');}catch{}}
function initialCourseRoute(){if(typeof window==='undefined')return;applyingRoute=true;const r=location.hash.slice(1).split('/');state.session=null;if(r[0]==='module'&&modules.some(m=>m.id===r[1])){state.module=r[1];state.page='module';state.tab=['learn','diagram','reference','compare','lab','recall','practice','review'].includes(r[2])?r[2]:'learn';state.lesson=Math.max(0,Math.min(mod().lessons.length-1,Number(r[3])||0));state.diagram=Math.max(0,Math.min(ds().length-1,Number(r[4])||0));state.target=Math.max(0,Math.min(ds()[state.diagram].targets.length-1,Number(r[5])||0));}else if(['exam','review','glossary','sources'].includes(r[0]))state.page=r[0];else if(['quiz','results'].includes(r[0])){try{const d=JSON.parse(localStorage.getItem('soma-cell-draft-v1')||'{}').state;if(d?.session?.questions?.length&&Number.isInteger(d.session.index)&&d.session.index>=0&&d.session.index<d.session.questions.length){Object.assign(state,d);state.page=r[0];}else state.page='home';}catch{state.page='home';}}else state.page='home';render();applyingRoute=false;}
if(typeof window!=='undefined'){if(!location.hash)location.replace('../#/chapter/3');window.addEventListener('hashchange',()=>{if(leave())initialCourseRoute();else saveCellPosition();});window.addEventListener('pagehide',saveCellPosition);initialCourseRoute();}

render();
